package com.travel.media; import java.time.Instant; public record MediaView(Long id,Long placeId,String originalFilename,String mimeType,long sizeBytes,String originalUrl,String thumbnailUrl,Instant createdAt){static MediaView from(Media m){return new MediaView(m.id,m.place==null?null:m.place.getId(),m.originalFilename,m.mimeType,m.sizeBytes,"/api/media/"+m.id+"/original","/api/media/"+m.id+"/thumbnail",m.createdAt);}}
